package dk.jamesbabz.madkursus.outbound.mealplan.details;
import java.util.UUID; import dk.jamesbabz.madkursus.outbound.recipe.details.RecipeEntity; import dk.jamesbabz.madkursus.service.models.PlannedRecipeStatus; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="planned_recipes") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class PlannedRecipeEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="meal_plan_id") private MealPlanEntity mealPlan; @ManyToOne @JoinColumn(name="recipe_id") private RecipeEntity recipe; private String recipeName; private int portions; private int sortOrder; @Enumerated(EnumType.STRING) private PlannedRecipeStatus status; public PlannedRecipeEntity(UUID id,RecipeEntity recipe,String recipeName,int portions,int sortOrder,PlannedRecipeStatus status){this.id=id;this.recipe=recipe;this.recipeName=recipeName;this.portions=portions;this.sortOrder=sortOrder;this.status=status;} public void update(RecipeEntity recipe,String recipeName,int portions,int sortOrder,PlannedRecipeStatus status){this.recipe=recipe;this.recipeName=recipeName;this.portions=portions;this.sortOrder=sortOrder;this.status=status;} void setMealPlan(MealPlanEntity p){mealPlan=p;} }
